@Composable private fun PersonRow(person: SocialPerson, click: () -> Unit) = TextButton(click, Modifier.fillMaxWidth()) { SocialAvatar(person); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f), horizontalAlignment = Alignment.Start) { Text(person.displayName); person.username?.let { Text("@$it", style = MaterialTheme.typography.bodySmall) } } }
@Composable private fun InvitationCard(invitation: SocialInvitation, review:(SocialInvitation)->Unit) = ElevatedCard(Modifier.fillMaxWidth()) { Column(Modifier.padding(16.dp)) { Text(invitation.title, fontWeight = FontWeight.SemiBold); Text(stringResource(R.string.social_invited_by, invitation.sender.displayName), style = MaterialTheme.typography.bodySmall); Button({review(invitation)}, Modifier.padding(top = 8.dp)) { Text(stringResource(R.string.social_review)) } } }
@Composable private fun EventCard(event: SocialEvent, open:()->Unit) = OutlinedCard(open,Modifier.fillMaxWidth()) { Column(Modifier.padding(16.dp)) { Text(event.name, fontWeight = FontWeight.SemiBold); Text(stringResource(R.string.social_hybrid)); event.locationName?.let { Text(it, style = MaterialTheme.typography.bodySmall) } } }
@Composable private fun GroupCard(group: SocialGroup, membership: () -> Unit) = OutlinedCard(Modifier.fillMaxWidth()) { Row(Modifier.padding(16.dp), verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text(group.name, fontWeight = FontWeight.SemiBold); Text(stringResource(R.string.social_members, group.memberCount), style = MaterialTheme.typography.bodySmall) }; TextButton(membership) { Text(stringResource(if (group.joined) R.string.social_leave else R.string.social_join)) } } }
@Composable private fun PostCard(post: SocialPost, profile: () -> Unit, cheer: () -> Unit, comments:()->Unit, safety: () -> Unit) = ElevatedCard(Modifier.fillMaxWidth()) { val cheerLabel=stringResource(if(post.viewerHasCheered)R.string.social_remove_cheer else R.string.social_add_cheer);Column { Row(Modifier.fillMaxWidth().padding(12.dp), verticalAlignment = Alignment.CenterVertically) { TextButton(profile, Modifier.weight(1f)) { SocialAvatar(post.author,36.dp); Spacer(Modifier.width(10.dp)); Column(horizontalAlignment=Alignment.Start){Text(post.author.displayName,fontWeight=FontWeight.SemiBold);post.activity?.startedAt?.let{Text(formatSocialDate(it),style=MaterialTheme.typography.bodySmall)}} }; IconButton(safety) { Icon(Icons.Outlined.MoreVert, stringResource(R.string.social_more)) } }; Box { post.activity?.route.routeCoordinates().takeIf { it.size > 1 }?.let { PlainstrideRouteMap(it, Modifier.fillMaxWidth().height(210.dp)) } ?: Surface(Modifier.fillMaxWidth().height(210.dp), color = MaterialTheme.colorScheme.surfaceVariant) { Box(contentAlignment = Alignment.Center) { Icon(Icons.Outlined.Route, stringResource(R.string.social_route), Modifier.size(44.dp)) } };post.activity?.let{activity->Surface(Modifier.align(Alignment.BottomCenter).fillMaxWidth(),color=MaterialTheme.colorScheme.scrim.copy(alpha=.72f)){Row(Modifier.padding(12.dp),horizontalArrangement=Arrangement.SpaceEvenly){ActivityStat(formatDistance(activity.distanceM),stringResource(R.string.social_distance));ActivityStat(formatDuration(activity.durationSecs),stringResource(R.string.social_time));ActivityStat(formatPace(activity.averagePaceSecsPerKm),stringResource(R.string.social_pace))}}} }; Column(Modifier.padding(16.dp)) { post.activity?.let { Text(it.title, fontWeight = FontWeight.SemiBold) }; post.caption?.let { Text(it, Modifier.padding(top = 6.dp)) }; Row(verticalAlignment = Alignment.CenterVertically) { IconButton(cheer, Modifier.sizeIn(minWidth=48.dp,minHeight=48.dp).semantics { contentDescription = cheerLabel }) { Icon(if (post.viewerHasCheered) Icons.Outlined.Favorite else Icons.Outlined.FavoriteBorder, null) }; Text(post.cheerCount.toString()); Spacer(Modifier.width(18.dp)); IconButton(comments,Modifier.sizeIn(minWidth=48.dp,minHeight=48.dp)){Icon(Icons.Outlined.ChatBubbleOutline,stringResource(R.string.social_comments))};Text(post.commentCount.toString()) } } } }

@Composable private fun ActivityStat(value:String,label:String)=Column(horizontalAlignment=Alignment.CenterHorizontally){Text(value,color=MaterialTheme.colorScheme.inverseOnSurface,fontWeight=FontWeight.Bold);Text(label,color=MaterialTheme.colorScheme.inverseOnSurface,style=MaterialTheme.typography.labelSmall)}
private fun formatDistance(value:Double?)=value?.let{"%.2f km".format(it/1000)} ?: "—"
private fun formatDuration(value:Int?)=value?.let{"%d:%02d".format(it/60,it%60)} ?: "—"
private fun formatPace(value:Double?)=value?.let{"%d:%02d /km".format(it.toInt()/60,it.toInt()%60)} ?: "—"
private fun formatSocialDate(value:String)=runCatching{java.time.OffsetDateTime.parse(value).format(java.time.format.DateTimeFormatter.ofLocalizedDateTime(java.time.format.FormatStyle.MEDIUM,java.time.format.FormatStyle.SHORT))}.getOrDefault("")

@Composable private fun CommentsDialog(post:SocialPost,comments:List<SocialComment>,add:(String)->Unit,delete:(SocialComment)->Unit,close:()->Unit){var body by rememberSaveable{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text(stringResource(R.string.social_comments_for,post.author.displayName))},text={Column{LazyColumn(Modifier.heightIn(max=320.dp)){items(comments,key=SocialComment::id){comment->Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(comment.author.displayName,fontWeight=FontWeight.SemiBold);Text(comment.body)};if(comment.canDelete)IconButton({delete(comment)}){Icon(Icons.Outlined.Delete,stringResource(R.string.social_delete_comment))}}}};OutlinedTextField(body,{body=it.take(500)},Modifier.fillMaxWidth(),label={Text(stringResource(R.string.social_add_comment))})}},confirmButton={TextButton({if(body.isNotBlank()){add(body);body=""}}){Text(stringResource(R.string.social_post_comment))}},dismissButton={TextButton(close){Text(stringResource(R.string.social_done))}})}

private fun JsonElement?.routeCoordinates(): List<MapCoordinate> {
    val root = this as? JsonObject ?: return emptyList()
    val raw = (root["coordinates"] ?: (root["geometry"] as? JsonObject)?.get("coordinates")) as? JsonArray ?: return emptyList()
    val line = if (raw.firstOrNull() is JsonPrimitive) listOf(raw) else raw.mapNotNull { it as? JsonArray }
    return line.mapNotNull { pair -> val lon=(pair.getOrNull(0) as? JsonPrimitive)?.doubleOrNull; val lat=(pair.getOrNull(1) as? JsonPrimitive)?.doubleOrNull; if(lat!=null&&lon!=null) MapCoordinate(lat,lon) else null }
}
@Composable private fun ProfileDialog(person:SocialPerson,close:()->Unit,connect:()->Unit,accept:()->Unit,remove:()->Unit){
 val context=LocalContext.current;val shareLabel=stringResource(R.string.social_share_award_text,person.displayName)
 AlertDialog(onDismissRequest=close,icon={Icon(Icons.Outlined.AccountCircle,null)},title={Text(person.displayName)},text={Column{person.username?.let{Text("@$it")};Text(stringResource(R.string.social_relationship,relationshipLabel(person.relationship)),Modifier.padding(top=8.dp));if(person.recognitions.isNotEmpty()){Text(stringResource(R.string.social_milestones,person.recognitions.size),Modifier.padding(top=12.dp));person.recognitions.filter{it.shareable}.forEach{award->val badge=badgeLabel(award.badgeId);TextButton({context.startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"$shareLabel · $badge"),null))}){Icon(Icons.Outlined.Share,null);Spacer(Modifier.width(8.dp));Text(stringResource(R.string.social_share_award_named,badge))}}}}},confirmButton={Row{when{person.relationship=="none"->TextButton(connect){Text(stringResource(R.string.social_connect))};person.relationship=="pending"&&person.connectionDirection=="incoming"->TextButton(accept){Text(stringResource(R.string.social_accept))};else->TextButton(remove){Text(stringResource(R.string.social_remove_connection))}};TextButton(close){Text(stringResource(R.string.social_done))}}})
}
@Composable private fun reportReasonLabel(reason:ReportReason)=stringResource(when(reason){ReportReason.HARASSMENT->R.string.social_reason_harassment;ReportReason.HATE->R.string.social_reason_hate;ReportReason.SPAM->R.string.social_reason_spam;ReportReason.SEXUAL->R.string.social_reason_sexual;ReportReason.VIOLENCE->R.string.social_reason_violence;ReportReason.PRIVACY->R.string.social_reason_privacy;ReportReason.OTHER->R.string.social_reason_other})
@Composable private fun relationshipLabel(value:String)=when(value){"accepted","connected"->stringResource(R.string.social_relationship_connected);"pending"->stringResource(R.string.social_relationship_pending);else->stringResource(R.string.social_relationship_none)}
@Composable private fun badgeLabel(value:String)=stringResource(R.string.social_award_badge)
